<?php /** @package Meridian_News */ $related = meridian_news_related_posts(); if ( $related->have_posts() ) : ?><section class="related-posts"><div class="section-heading"><p class="eyebrow"><?php esc_html_e( 'More to read', 'meridian-news' ); ?></p><h2><?php esc_html_e( 'Related news', 'meridian-news' ); ?></h2></div><div class="card-grid card-grid--three"><?php while ( $related->have_posts() ) : $related->the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div></section><?php endif; wp_reset_postdata(); ?>
